import type { MetadataRoute } from 'next'
import { createClient } from '@/lib/supabase/server'

export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
  const baseUrl = process.env.NEXT_PUBLIC_APP_URL ?? 'https://app.inkos.io'

  const staticRoutes: MetadataRoute.Sitemap = [
    {
      url: baseUrl,
      lastModified: new Date(),
      changeFrequency: 'weekly',
      priority: 1,
    },
    {
      url: `${baseUrl}/login`,
      lastModified: new Date(),
      changeFrequency: 'monthly',
      priority: 0.5,
    },
    {
      url: `${baseUrl}/signup`,
      lastModified: new Date(),
      changeFrequency: 'monthly',
      priority: 0.8,
    },
  ]

  // Dynamically include public booking pages for active studios
  let studioRoutes: MetadataRoute.Sitemap = []
  try {
    const supabase = await createClient()
    const { data: studios } = await supabase
      .from('studios')
      .select('slug, updated_at')
      .eq('is_public', true)
      .limit(500)

    if (studios) {
      studioRoutes = studios.map((s) => ({
        url: `${baseUrl}/book/${s.slug}`,
        lastModified: new Date(s.updated_at),
        changeFrequency: 'weekly' as const,
        priority: 0.7,
      }))
    }
  } catch {
    // Supabase unavailable during build — return static routes only
  }

  return [...staticRoutes, ...studioRoutes]
}

