/**
 * LocalBusinessJsonLd — server component.
 * Renders a JSON-LD <script> block for /book/[studioSlug] for rich search results.
 * Fetches studio data server-side so it's available in initial HTML.
 */
import { createClient } from '@/lib/supabase/server'

interface Props {
  studioSlug: string
}

interface StudioRow {
  name: string
  slug: string
  brand_color: string | null
  logo_url: string | null
  // Optional fields that may exist
  phone?: string | null
  website?: string | null
  street?: string | null
  city?: string | null
  state?: string | null
  zip?: string | null
  country?: string | null
}

export async function LocalBusinessJsonLd({ studioSlug }: Props) {
  const baseUrl = process.env.NEXT_PUBLIC_APP_URL ?? 'https://app.inkos.io'

  let studio: StudioRow | null = null
  try {
    const supabase = await createClient()
    const { data } = await supabase
      .from('studios')
      .select('name, slug, brand_color, logo_url')
      .eq('slug', studioSlug)
      .single()
    studio = data
  } catch {
    // Studio not found — no JSON-LD emitted
  }

  if (!studio) return null

  const ld = {
    '@context': 'https://schema.org',
    '@type': ['LocalBusiness', 'HealthAndBeautyBusiness'],
    name: studio.name,
    url: `${baseUrl}/book/${studioSlug}`,
    ...(studio.logo_url && { image: studio.logo_url }),
    priceRange: '$$',
    sameAs: [],
    // booking action
    potentialAction: {
      '@type': 'ReserveAction',
      target: {
        '@type': 'EntryPoint',
        urlTemplate: `${baseUrl}/book/${studioSlug}`,
        inLanguage: 'en',
        actionPlatform: [
          'https://schema.org/DesktopWebPlatform',
          'https://schema.org/MobileWebPlatform',
        ],
      },
      result: {
        '@type': 'Reservation',
        name: 'Tattoo appointment',
      },
    },
  }

  return (
    <script
      type="application/ld+json"
      // biome-ignore lint/security/noDangerouslySetInnerHtml: controlled JSON-LD
      dangerouslySetInnerHTML={{ __html: JSON.stringify(ld) }}
    />
  )
}

