/**
 * WebVitalsReporter — thin client component.
 * Subscribes to Core Web Vitals (LCP, INP, CLS, FCP, TTFB) and forwards
 * them to Sentry Performance + PostHog for RUM.
 *
 * Uses dynamic import so the web-vitals bundle is not in the critical path.
 */
import { useEffect } from 'react'

export function WebVitalsReporter() {
  useEffect(() => {
    async function init() {
      const { onLCP, onINP, onCLS, onFCP, onTTFB } = await import('web-vitals')

      function report(metric: {
        name: string
        value: number
        rating: string
        id: string
      }) {
        // Sentry
        if (typeof window !== 'undefined' && 'Sentry' in window) {
          const sentry = (window as unknown as { Sentry: { captureEvent: (e: unknown) => void } }).Sentry
          sentry.captureEvent({
            message: `Web Vital: ${metric.name}`,
            level: 'info',
            extra: {
              name: metric.name,
              value: metric.value,
              rating: metric.rating,
              id: metric.id,
            },
          })
        }

        // PostHog (if available)
        if (typeof window !== 'undefined' && 'posthog' in window) {
          const ph = (window as unknown as { posthog: { capture: (name: string, props: unknown) => void } }).posthog
          ph.capture('web_vital', {
            name: metric.name,
            value: metric.value,
            rating: metric.rating,
          })
        }
      }

      onLCP(report)
      onINP(report)
      onCLS(report)
      onFCP(report)
      onTTFB(report)
    }

    void init()
  }, [])

  return null
}

