/**
 * Playwright smoke test fixtures.
 *
 * Provides a `signedInPage` fixture that authenticates programmatically
 * via Supabase API (no UI login walk-through needed for most tests).
 * This saves ~30s per test.
 *
 * Usage:
 *   import { test, expect, signedInPage } from '../smoke/fixtures'
 *   test('dashboard loads', async ({ signedInPage: page }) => { ... })
 */
import { test as base, type Page } from '@playwright/test'

const TEST_EMAIL = process.env.TEST_USER_EMAIL ?? 'smoketest@inkos.dev'
const TEST_PASSWORD = process.env.TEST_USER_PASSWORD ?? 'InkOS_Smoke_2026!'

interface Fixtures {
  signedInPage: Page
}

export const test = base.extend<Fixtures>({
  signedInPage: async ({ page }, use) => {
    const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL
    const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY

    if (!supabaseUrl || !supabaseAnonKey) {
      // Fall back to UI login when env vars are missing (e.g. CI without secrets)
      await page.goto('/login')
      await page.fill('input[name="email"]', TEST_EMAIL)
      await page.fill('input[name="password"]', TEST_PASSWORD)
      await page.click('button[type="submit"]')
      await page.waitForURL('**/dashboard', { timeout: 15_000 })
    } else {
      // Programmatic sign-in — call Supabase REST auth directly
      const res = await fetch(`${supabaseUrl}/auth/v1/token?grant_type=password`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          apikey: supabaseAnonKey,
        },
        body: JSON.stringify({ email: TEST_EMAIL, password: TEST_PASSWORD }),
      })

      if (!res.ok) {
        throw new Error(`Supabase auth failed: ${res.statusText}`)
      }

      const auth = (await res.json()) as {
        access_token: string
        refresh_token: string
      }

      // Inject session cookies that match what @supabase/ssr expects
      await page.context().addCookies([
        {
          name: 'sb-access-token',
          value: auth.access_token,
          domain: 'localhost',
          path: '/',
          httpOnly: true,
          secure: false,
          sameSite: 'Lax',
        },
        {
          name: 'sb-refresh-token',
          value: auth.refresh_token,
          domain: 'localhost',
          path: '/',
          httpOnly: true,
          secure: false,
          sameSite: 'Lax',
        },
      ])
    }

    await use(page)
  },
})

