interface LaunchMetric {
  label: string
  value: string
  status: 'green' | 'yellow' | 'red' | 'unknown'
  detail: string
}

const LHCI_CATEGORIES = ['Performance', 'Accessibility', 'Best Practices', 'SEO'] as const

function LaunchMetricCard({ metric }: { metric: LaunchMetric }) {
  const ring =
    metric.status === 'green'
      ? 'border-emerald-500/40 bg-emerald-500/5'
      : metric.status === 'yellow'
        ? 'border-amber-500/40 bg-amber-500/5'
        : metric.status === 'red'
          ? 'border-destructive/40 bg-destructive/5'
          : 'border-border/40 bg-muted/20'

  const dot =
    metric.status === 'green'
      ? 'bg-emerald-500'
      : metric.status === 'yellow'
        ? 'bg-amber-500'
        : metric.status === 'red'
          ? 'bg-destructive'
          : 'bg-muted-foreground/30'

  return (
    <div className={`rounded-xl border p-4 space-y-2 ${ring}`}>
      <div className="flex items-center gap-2">
        <span className={`inline-block h-2 w-2 rounded-full ${dot}`} />
        <span className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
          {metric.label}
        </span>
      </div>
      <p className="text-3xl font-extrabold tabular-nums leading-none">{metric.value}</p>
      <p className="text-xs text-muted-foreground">{metric.detail}</p>
    </div>
  )
}

function LaunchReadinessDashboard() {
  const [lhciData, setLhciData] = React.useState<Record<string, number> | null>(null)

  React.useEffect(() => {
    fetch('/tests/perf/lhci-results.json')
      .then((r) => r.json() as Promise<Record<string, number>>)
      .then(setLhciData)
      .catch(() => {
        setLhciData(null)
      })
  }, [])

  const lighthouseMetrics: LaunchMetric[] = LHCI_CATEGORIES.map((cat) => {
    const score = lhciData?.[cat.toLowerCase()] ?? null
    return {
      label: cat,
      value: score !== null ? `${Math.round(score * 100)}` : '—',
      status:
        score === null ? 'unknown' : score >= 0.95 ? 'green' : score >= 0.8 ? 'yellow' : 'red',
      detail:
        score !== null
          ? score >= 0.95
            ? 'Target ≥ 95 — PASS'
            : 'Below 95 target'
          : 'Run: pnpm ci:perf',
    }
  })

  const metrics: LaunchMetric[] = [
    ...lighthouseMetrics,
    {
      label: 'Axe Violations',
      value: '—',
      status: 'unknown',
      detail: 'Run: pnpm dlx @axe-core/cli http://localhost:3100 --tags wcag21aa',
    },
    {
      label: 'Bundle Size',
      value: '~7.9 MB',
      status: 'green',
      detail: 'Sprint 11 baseline (static). Run ANALYZE=true pnpm build for treemap.',
