    {
      label: 'Uptime / 30d',
      value: '—',
      status: 'unknown',
      detail: 'Configure Better Stack at status.inkos.app to track uptime.',
    },
  ]

  const passCount = metrics.filter((m) => m.status === 'green').length
  const readinessLabel =
    passCount === metrics.length
      ? 'LAUNCH READY'
      : `${passCount}/${metrics.length} gates green`

  const readinessBadge =
    passCount === metrics.length
      ? 'bg-emerald-500 text-white'
      : passCount >= metrics.length * 0.7
        ? 'bg-amber-500 text-white'
        : 'bg-destructive text-destructive-foreground'

  return (
    <div className="space-y-8">
      <div className={`inline-flex items-center gap-2 rounded-full px-4 py-1.5 text-sm font-semibold ${readinessBadge}`}>
        {readinessLabel}
      </div>

      <div className="grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-4">
        {metrics.map((m) => (
          <LaunchMetricCard key={m.label} metric={m} />
        ))}
      </div>

      <div className="rounded-xl border border-border/60 bg-muted/20 p-5 space-y-3">
        <p className="text-sm font-semibold">Run gates manually</p>
        <div className="space-y-2 font-mono text-xs text-muted-foreground">
