            ['Build + type check', 'rm -rf .next && pnpm typecheck && pnpm lint --max-warnings=0 && pnpm build'],
            ['Lighthouse CI (≥95)', 'pnpm ci:perf'],
            ['Axe a11y (0 serious/critical)', 'pnpm dlx @axe-core/cli http://localhost:3100 --tags wcag21aa'],
            ['Smoke tests (15/15)', 'pnpm test:smoke'],
            ['Bundle analyzer', 'ANALYZE=true pnpm build'],
